params.spec:
{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "One hexagon per GCE instance, keyed on instance_id and labelled with instance_name. Ordered worst first by the selected metric. Click any hexagon to drill down.",
  "usermeta": {
    "x_gce_hexmap": true
  },
  "padding": {
    "top": 10,
    "left": 10,
    "right": 10,
    "bottom": 15
  },
  "data": [
    {
      "name": "ts_probe",
      "url": {
        "%type%": "esql",
        "%context%": true,
        "%timefield%": "@timestamp",
        "query": "ROW round_key = CONCAT(TO_STRING(?_tstart), \"|\", TO_STRING(?_tend)), fetched_at = NOW()"
      }
    },
    {
      "name": "raw_all",
      "url": {
        "%type%": "esql",
        "%context%": true,
        "%timefield%": "@timestamp",
        "query": "SET unmapped_fields = \"nullify\";\nTS metrics-googlecloudmonitoringreceiver.otel-default | WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend AND resource.attributes.gcp.resource_type == \"gce_instance\" AND resource.attributes.instance_id IS NOT NULL AND resource.attributes.instance_id != \"\" | STATS cpu_min = MIN(MIN_OVER_TIME(`compute.googleapis.com/instance/cpu/utilization`)), cpu_max = MAX(MAX_OVER_TIME(`compute.googleapis.com/instance/cpu/utilization`)), cpu_avg = AVG(AVG_OVER_TIME(`compute.googleapis.com/instance/cpu/utilization`)), cpu_last = MAX(LAST_OVER_TIME(`compute.googleapis.com/instance/cpu/utilization`)), ram_used_min = MIN(MIN_OVER_TIME(`compute.googleapis.com/instance/memory/balloon/ram_used`)), ram_used_max = MAX(MAX_OVER_TIME(`compute.googleapis.com/instance/memory/balloon/ram_used`)), ram_used_avg = AVG(AVG_OVER_TIME(`compute.googleapis.com/instance/memory/balloon/ram_used`)), ram_used_last = MAX(LAST_OVER_TIME(`compute.googleapis.com/instance/memory/balloon/ram_used`)), ram_size = MAX(MAX_OVER_TIME(`compute.googleapis.com/instance/memory/balloon/ram_size`)), instance_name = MAX(attributes.instance_name) BY instance_id = resource.attributes.instance_id, zone = resource.attributes.zone | EVAL cpu_min = cpu_min * 100, cpu_max = cpu_max * 100, cpu_avg = cpu_avg * 100, cpu_last = cpu_last * 100, mem_min = CASE(ram_size > 0, TO_DOUBLE(ram_used_min) / TO_DOUBLE(ram_size) * 100, NULL), mem_max = CASE(ram_size > 0, TO_DOUBLE(ram_used_max) / TO_DOUBLE(ram_size) * 100, NULL), mem_avg = CASE(ram_size > 0, TO_DOUBLE(ram_used_avg) / TO_DOUBLE(ram_size) * 100, NULL), mem_last = CASE(ram_size > 0, TO_DOUBLE(ram_used_last) / TO_DOUBLE(ram_size) * 100, NULL), display_name = CASE(instance_name IS NULL, instance_id, instance_name), round_key = CONCAT(TO_STRING(?_tstart), \"|\", TO_STRING(?_tend)), fetched_at = NOW() | KEEP instance_id, instance_name, display_name, zone, cpu_min, cpu_max, cpu_avg, cpu_last, mem_min, mem_max, mem_avg, mem_last, round_key, fetched_at | LIMIT 10000"
      }
    },
    {
      "name": "ranked_cpu_min",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.cpu_min == null ? 1e12 : -datum.cpu_min * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "instance_id"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "ranked_cpu_max",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.cpu_max == null ? 1e12 : -datum.cpu_max * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "instance_id"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "ranked_cpu_avg",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.cpu_avg == null ? 1e12 : -datum.cpu_avg * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "instance_id"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "ranked_cpu_last",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.cpu_last == null ? 1e12 : -datum.cpu_last * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "instance_id"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "ranked_mem_min",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.mem_min == null ? 1e12 : -datum.mem_min * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "instance_id"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "ranked_mem_max",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.mem_max == null ? 1e12 : -datum.mem_max * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "instance_id"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "ranked_mem_avg",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.mem_avg == null ? 1e12 : -datum.mem_avg * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "instance_id"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "ranked_mem_last",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "sort_key",
          "expr": "datum.mem_last == null ? 1e12 : -datum.mem_last * 1000000"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "sort_key",
              "instance_id"
            ],
            "order": [
              "ascending",
              "ascending"
            ]
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "active_rank"
          ]
        }
      ]
    },
    {
      "name": "active",
      "values": [],
      "on": [
        {
          "trigger": "ts_round !== '' && active_round !== '' && active_round !== ts_round",
          "remove": "true"
        },
        {
          "trigger": "metric === 'cpu' && agg === 'min' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_cpu_min')"
        },
        {
          "trigger": "metric === 'cpu' && agg === 'max' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_cpu_max')"
        },
        {
          "trigger": "metric === 'cpu' && agg === 'avg' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_cpu_avg')"
        },
        {
          "trigger": "metric === 'cpu' && agg === 'last' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_cpu_last')"
        },
        {
          "trigger": "metric === 'mem' && agg === 'min' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_mem_min')"
        },
        {
          "trigger": "metric === 'mem' && agg === 'max' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_mem_max')"
        },
        {
          "trigger": "metric === 'mem' && agg === 'avg' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_mem_avg')"
        },
        {
          "trigger": "metric === 'mem' && agg === 'last' && len_raw > 0 && raw_round === ts_round && ts_round !== ''",
          "remove": "true",
          "insert": "data('ranked_mem_last')"
        }
      ]
    },
    {
      "name": "instances",
      "source": "active",
      "transform": [
        {
          "type": "formula",
          "as": "active_val",
          "expr": "metric=='cpu' ? (agg=='min' ? datum.cpu_min : agg=='max' ? datum.cpu_max : agg=='avg' ? datum.cpu_avg : datum.cpu_last) : (agg=='min' ? datum.mem_min : agg=='max' ? datum.mem_max : agg=='avg' ? datum.mem_avg : datum.mem_last)"
        },
        {
          "type": "formula",
          "as": "index0",
          "expr": "datum.active_rank - 1"
        },
        {
          "type": "formula",
          "as": "col",
          "expr": "datum.index0 % gridCols"
        },
        {
          "type": "formula",
          "as": "row",
          "expr": "floor(datum.index0 / gridCols)"
        },
        {
          "type": "formula",
          "as": "x",
          "expr": "datum.col * gapX + (datum.row % 2 == 1 ? gapX / 2 : 0) + hexR + 5"
        },
        {
          "type": "formula",
          "as": "y",
          "expr": "datum.row * gapY + hexR + 5 + hexOffsetY"
        },
        {
          "type": "formula",
          "as": "hexSize",
          "expr": "hexR * hexR * 3.46"
        }
      ]
    },
    {
      "name": "util_counts",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "v",
          "expr": "agg == 'min' ? datum.cpu_min : agg == 'max' ? datum.cpu_max : agg == 'avg' ? datum.cpu_avg : datum.cpu_last"
        },
        {
          "type": "formula",
          "as": "bucket",
          "expr": "datum.v == null ? 3 : (datum.v >= 90 ? 2 : datum.v >= 70 ? 1 : 0)"
        },
        {
          "type": "aggregate",
          "groupby": [
            "bucket"
          ],
          "ops": [
            "count"
          ],
          "as": [
            "count"
          ]
        }
      ]
    },
    {
      "name": "util_legend_stops",
      "values": [
        {
          "label": "≥ 90%",
          "val": 90,
          "bucket": 2,
          "is_nodata": false
        },
        {
          "label": "70 – 89%",
          "val": 70,
          "bucket": 1,
          "is_nodata": false
        },
        {
          "label": "< 70%",
          "val": 0,
          "bucket": 0,
          "is_nodata": false
        },
        {
          "label": "No data",
          "val": null,
          "bucket": 3,
          "is_nodata": true
        }
      ],
      "transform": [
        {
          "type": "lookup",
          "from": "util_counts",
          "key": "bucket",
          "fields": [
            "bucket"
          ],
          "values": [
            "count"
          ],
          "as": [
            "count"
          ],
          "default": 0
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "idx"
          ]
        }
      ]
    },
    {
      "name": "mem_counts",
      "source": "raw_all",
      "transform": [
        {
          "type": "formula",
          "as": "v",
          "expr": "agg == 'min' ? datum.mem_min : agg == 'max' ? datum.mem_max : agg == 'avg' ? datum.mem_avg : datum.mem_last"
        },
        {
          "type": "formula",
          "as": "bucket",
          "expr": "datum.v == null ? 3 : (datum.v >= 90 ? 2 : datum.v >= 70 ? 1 : 0)"
        },
        {
          "type": "aggregate",
          "groupby": [
            "bucket"
          ],
          "ops": [
            "count"
          ],
          "as": [
            "count"
          ]
        }
      ]
    },
    {
      "name": "mem_legend_stops",
      "values": [
        {
          "label": "≥ 90%",
          "val": 90,
          "bucket": 2,
          "is_nodata": false
        },
        {
          "label": "70 – 89%",
          "val": 70,
          "bucket": 1,
          "is_nodata": false
        },
        {
          "label": "< 70%",
          "val": 0,
          "bucket": 0,
          "is_nodata": false
        },
        {
          "label": "No data",
          "val": null,
          "bucket": 3,
          "is_nodata": true
        }
      ],
      "transform": [
        {
          "type": "lookup",
          "from": "mem_counts",
          "key": "bucket",
          "fields": [
            "bucket"
          ],
          "values": [
            "count"
          ],
          "as": [
            "count"
          ],
          "default": 0
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "idx"
          ]
        }
      ]
    },
    {
      "name": "spinner_dots",
      "values": [
        {
          "i": 0
        },
        {
          "i": 1
        },
        {
          "i": 2
        },
        {
          "i": 3
        },
        {
          "i": 4
        },
        {
          "i": 5
        },
        {
          "i": 6
        },
        {
          "i": 7
        }
      ]
    },
    {
      "name": "pills",
      "values": [
        {
          "id": "cpu",
          "label": "CPU %",
          "group": "metric",
          "x": 69,
          "w": 58
        },
        {
          "id": "mem",
          "label": "Memory %",
          "group": "metric",
          "x": 133,
          "w": 78
        },
        {
          "id": "min",
          "label": "Min",
          "group": "agg",
          "x": 325,
          "w": 36
        },
        {
          "id": "max",
          "label": "Max",
          "group": "agg",
          "x": 365,
          "w": 36
        },
        {
          "id": "avg",
          "label": "Avg",
          "group": "agg",
          "x": 405,
          "w": 36
        },
        {
          "id": "last",
          "label": "Last",
          "group": "agg",
          "x": 445,
          "w": 40
        }
      ]
    },
    {
      "name": "menu_items_data",
      "values": [
        {
          "id": "details",
          "label": "1. View details",
          "idx": 0
        },
        {
          "id": "metrics",
          "label": "2. View metrics in Discover",
          "idx": 1
        }
      ]
    },
    {
      "name": "menu_visible",
      "values": [
        {
          "_": 0
        }
      ],
      "transform": [
        {
          "type": "filter",
          "expr": "selected_instance != null"
        }
      ]
    },
    {
      "name": "menu_items_visible",
      "source": "menu_items_data",
      "transform": [
        {
          "type": "filter",
          "expr": "selected_instance != null"
        }
      ]
    },
    {
      "name": "spark_raw",
      "url": {
        "%type%": "esql",
        "%context%": true,
        "%timefield%": "@timestamp",
        "query": "SET unmapped_fields = \"nullify\";\nFROM metrics-googlecloudmonitoringreceiver.otel-default | WHERE @timestamp >= ?_tstart AND @timestamp <= ?_tend AND resource.attributes.gcp.resource_type == \"gce_instance\" AND resource.attributes.instance_id IS NOT NULL | STATS s_cpu = AVG(`compute.googleapis.com/instance/cpu/utilization`), s_used = AVG(`compute.googleapis.com/instance/memory/balloon/ram_used`), s_size = MAX(`compute.googleapis.com/instance/memory/balloon/ram_size`) BY entity_id = resource.attributes.instance_id, t = BUCKET(@timestamp, 40, ?_tstart, ?_tend) | EVAL s_cpu = s_cpu * 100, s_mem = CASE(s_size > 0, s_used / TO_DOUBLE(s_size) * 100, NULL) | KEEP entity_id, t, s_cpu, s_mem | SORT entity_id, t | LIMIT 10000"
      }
    },
    {
      "name": "spark_series",
      "source": "spark_raw",
      "transform": [
        {
          "type": "filter",
          "expr": "tooltip && tooltip.instance_id && datum.entity_id === tooltip.instance_id"
        },
        {
          "type": "formula",
          "as": "v",
          "expr": "metric == 'cpu' ? datum.s_cpu : datum.s_mem"
        },
        {
          "type": "collect",
          "sort": {
            "field": "t",
            "order": "ascending"
          }
        }
      ]
    },
    {
      "name": "spark_stat",
      "source": "spark_series",
      "transform": [
        {
          "type": "aggregate",
          "fields": [
            "v",
            "v",
            "v"
          ],
          "ops": [
            "max",
            "mean",
            "valid"
          ],
          "as": [
            "vmax",
            "vavg",
            "vn"
          ]
        }
      ]
    }
  ],
  "signals": [
    {
      "name": "metric",
      "value": "cpu",
      "on": [
        {
          "events": "@pill_bg:click",
          "update": "datum.group === 'metric' ? datum.id : metric"
        }
      ]
    },
    {
      "name": "agg",
      "value": "avg",
      "on": [
        {
          "events": "@pill_bg:click",
          "update": "datum.group === 'agg' ? datum.id : agg"
        }
      ]
    },
    {
      "name": "len_raw",
      "update": "length(data('raw_all'))"
    },
    {
      "name": "len_active",
      "update": "length(data('active'))"
    },
    {
      "name": "ts_round",
      "update": "data('ts_probe')[0] ? data('ts_probe')[0].round_key : ''"
    },
    {
      "name": "time_from",
      "update": "ts_round !== '' && indexof(ts_round, '|') > 0 ? slice(ts_round, 0, indexof(ts_round, '|')) : ''"
    },
    {
      "name": "time_to",
      "update": "ts_round !== '' && indexof(ts_round, '|') > 0 ? slice(ts_round, indexof(ts_round, '|') + 1) : ''"
    },
    {
      "name": "g_param",
      "update": "time_from !== '' && time_to !== '' ? '_g=(time:(from:%27' + time_from + '%27,to:%27' + time_to + '%27))&' : ''"
    },
    {
      "name": "raw_round",
      "update": "data('raw_all')[0] ? data('raw_all')[0].round_key : ''"
    },
    {
      "name": "active_round",
      "update": "raw_round"
    },
    {
      "name": "raw_fetched_str",
      "update": "data('raw_all')[0] ? data('raw_all')[0].fetched_at : ''"
    },
    {
      "name": "active_fetched",
      "update": "raw_fetched_str !== '' ? toDate(raw_fetched_str) : 0"
    },
    {
      "name": "tick",
      "value": 0,
      "on": [
        {
          "events": {
            "type": "timer",
            "throttle": 100
          },
          "update": "now()"
        }
      ]
    },
    {
      "name": "url_change_at",
      "value": 0,
      "on": [
        {
          "events": {
            "source": "window",
            "type": "hashchange"
          },
          "update": "now()"
        },
        {
          "events": {
            "source": "window",
            "type": "popstate"
          },
          "update": "now()"
        }
      ]
    },
    {
      "name": "fetch_tracker",
      "init": "{seen: 0, arrived_at: 0}",
      "on": [
        {
          "events": {
            "signal": "tick"
          },
          "update": "active_fetched > 0 && active_fetched !== fetch_tracker.seen ? {seen: active_fetched, arrived_at: tick} : fetch_tracker"
        }
      ]
    },
    {
      "name": "loading_raw",
      "update": "len_active === 0 || ts_round === '' || active_round === '' || active_round !== ts_round || (url_change_at > 0 && fetch_tracker.arrived_at < url_change_at)"
    },
    {
      "name": "loading_started_at",
      "value": 0,
      "on": [
        {
          "events": {
            "signal": "tick"
          },
          "update": "loading_raw ? (loading_started_at === 0 ? tick : loading_started_at) : 0"
        }
      ]
    },
    {
      "name": "loading_elapsed",
      "update": "loading_started_at > 0 ? tick - loading_started_at : 0"
    },
    {
      "name": "no_data",
      "update": "loading_raw && ts_round !== '' && len_raw === 0 && loading_elapsed > 2000"
    },
    {
      "name": "loading",
      "update": "loading_raw && !no_data"
    },
    {
      "name": "loading_timeout",
      "update": "loading && loading_elapsed > 15000"
    },
    {
      "name": "total_instances",
      "update": "len_raw"
    },
    {
      "name": "legendW",
      "value": 150
    },
    {
      "name": "buttonsH",
      "value": 34
    },
    {
      "name": "availW",
      "update": "width - 20 - legendW"
    },
    {
