    {
      "name": "hexRInitial",
      "update": "min(availW / (idealCols * 2 + 0), availH / (idealRows * 2 + 0))"
    },
    {
      "name": "maxColsAtHexR",
      "update": "max(idealCols, floor(availW / (max(3, hexRInitial) * 2)))"
    },
    {
      "name": "maxColsAtMinR",
      "update": "max(1, floor(availW / (3 * 2)))"
    },
    {
      "name": "gridCols",
      "update": "max(1, min(total_instances, min(maxColsAtHexR, maxColsAtMinR)))"
    },
    {
      "name": "gridRows",
      "update": "max(1, ceil(total_instances / gridCols))"
    },
    {
      "name": "rByWidth",
      "update": "availW / (gridCols * 1.76 + 0.88)"
